# shellcheck shell=bash
# versioner CHANGELOG.md generation
#
# Walks the full reachable history (topological, oldest first) and groups
# conventional commits under the version computed AT that commit: a bump
# commit opens a new section; no-bump commits join the section that is
# current. Non-conventional and ignored commits are omitted, so the changelog
# and the computed version can never disagree.
# Newest section first. Regenerated whole each time — do not edit by hand.

_changelog_entry() {
	local h="$1" date="$2" msg="$3" header entry newv
	header="${msg%%$'\n'*}"
	config_is_ignored "$header" && return 0
	parse_bump "$header" "$msg" || return 0
	case "${BUMP_LEVEL:-}" in
	major)
		_CL_MAJOR=$((_CL_MAJOR + 1))
		_CL_MINOR=0
		_CL_PATCH=0
		;;
	minor)
		_CL_MINOR=$((_CL_MINOR + 1))
		_CL_PATCH=0
		;;
	patch) _CL_PATCH=$((_CL_PATCH + 1)) ;;
	esac
	newv="${_CL_MAJOR}.${_CL_MINOR}.${_CL_PATCH}"
	if [ "$newv" != "$_CL_VER" ]; then
		if [ -n "$_CL_ENTRIES" ]; then
			_CL_SECTIONS+=("${_CL_VER}"$'\x1f'"${_CL_DATE}"$'\x1f'"${_CL_ENTRIES}")
		fi
		_CL_VER="$newv"
		_CL_ENTRIES=""
		_CL_DATE=""
	fi
	entry="- ${BUMP_TYPE}"
	if [ -n "$BUMP_SCOPE" ]; then
		entry="${entry}(${BUMP_SCOPE})"
	fi
	entry="${entry}: ${BUMP_SUBJECT} (${h:0:$HASH_LEN})"
	if [ "$BUMP_BREAKING" = 1 ]; then
		entry="${entry} **BREAKING**"
	fi
	_CL_ENTRIES="${_CL_ENTRIES}${entry}"$'\n'
	_CL_DATE="$date"
	return 0
}

changelog_generate() {
	local ref="${1:-HEAD}" out_file="${2:-CHANGELOG.md}"
	local i rec sv sd se
	_CL_MAJOR=0
	_CL_MINOR=0
	_CL_PATCH=0
	_CL_VER="0.0.0"
	_CL_DATE=""
	_CL_ENTRIES=""
	_CL_SECTIONS=()
	history_each "$ref" _changelog_entry || return 1
	if [ -n "$_CL_ENTRIES" ]; then
		_CL_SECTIONS+=("${_CL_VER}"$'\x1f'"${_CL_DATE}"$'\x1f'"${_CL_ENTRIES}")
	fi
	{
		echo '# Changelog'
		echo
		echo "_Generated by versioner on $(date +%Y-%m-%d). Conventional commits only; do not edit by hand._"
		for ((i = ${#_CL_SECTIONS[@]} - 1; i >= 0; i--)); do
			rec="${_CL_SECTIONS[$i]}"
			sv="${rec%%$'\x1f'*}"
			rec="${rec#*$'\x1f'}"
			sd="${rec%%$'\x1f'*}"
			se="${rec#*$'\x1f'}"
			echo
			echo "## ${sv} - ${sd}"
			echo
			printf '%s' "$se"
		done
	} >"$out_file"
}
